<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');
$campaignId=(int)($_GET['campaign_id']??$_POST['campaign_id']??0);$campaigns=pg_query($conn,'SELECT id,title,status FROM feedback_campaigns ORDER BY created_at DESC');$campaign=null;if($campaignId){$r=pg_query_params($conn,'SELECT * FROM feedback_campaigns WHERE id=$1',[$campaignId]);$campaign=$r&&pg_num_rows($r)?pg_fetch_assoc($r):null;}$error='';$issued=$_SESSION['issued_participant']??null;unset($_SESSION['issued_participant']);
if($_SERVER['REQUEST_METHOD']==='POST'&&$campaign){if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired.';else{$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='create'){$name=trim($_POST['full_name']??'');$group=trim($_POST['group_name']??'');$code=strtoupper(trim($_POST['participant_code']??''));if($code==='')$code='FB-'.strtoupper(bin2hex(random_bytes(3)));$password=trim($_POST['password']??'');if($password===''){$chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%';$password='';for($i=0;$i<14;$i++)$password.=$chars[random_int(0,strlen($chars)-1)];}if($campaign['status']!=='draft')$error='Account creation is locked after the campaign starts.';elseif(!verify_admin_password($conn,$_SESSION['admin_id'],$_POST['admin_password']??''))$error='Correct administrator password is required.';elseif($name==='')$error='Participant name is required.';elseif(!preg_match('/^[A-Z0-9_-]{4,80}$/',$code))$error='Code must be 4–80 letters, numbers, dashes, or underscores.';elseif(strlen($password)<8)$error='Password must contain at least 8 characters.';else{$ok=pg_query_params($conn,'INSERT INTO feedback_participants(campaign_id,participant_code,full_name,group_name,password_hash) VALUES($1,$2,$3,$4,$5)',[$campaignId,$code,$name,$group,password_hash($password,PASSWORD_DEFAULT)]);if($ok){$_SESSION['issued_participant']=['code'=>$code,'password'=>$password,'name'=>$name];audit_log($conn,'feedback_participant_created','feedback_campaign',$campaignId,['participant_code'=>$code]);redirect('index.php?campaign_id='.$campaignId);}else$error='That participant code is already used.';}}
elseif($action==='toggle'&&$id){pg_query_params($conn,"UPDATE feedback_participants SET status=CASE WHEN status='disabled' THEN 'active' ELSE 'disabled' END WHERE id=$1 AND campaign_id=$2 AND status<>'responded'",[$id,$campaignId]);redirect('index.php?campaign_id='.$campaignId);}elseif($action==='reset'&&$id){$password=substr(strtoupper(bin2hex(random_bytes(5))),0,8);$r=pg_query_params($conn,"UPDATE feedback_participants SET password_hash=$1 WHERE id=$2 AND campaign_id=$3 AND status<>'responded' RETURNING participant_code,full_name",[password_hash($password,PASSWORD_DEFAULT),$id,$campaignId]);if($r&&pg_num_rows($r)){$_SESSION['issued_participant']=['code'=>pg_fetch_result($r,0,'participant_code'),'password'=>$password,'name'=>pg_fetch_result($r,0,'full_name')];redirect('index.php?campaign_id='.$campaignId);}}}}
$participants=$campaign?pg_query_params($conn,'SELECT * FROM feedback_participants WHERE campaign_id=$1 ORDER BY created_at DESC',[$campaignId]):null;$totalAll=$totalActive=$totalResponded=$totalDisabled=0;if($campaign){$stats=pg_query_params($conn,"SELECT COUNT(*) total,COUNT(*) FILTER(WHERE status='active') active,COUNT(*) FILTER(WHERE status='responded') responded,COUNT(*) FILTER(WHERE status='disabled') disabled FROM feedback_participants WHERE campaign_id=$1",[$campaignId]);if($stats){$sr=pg_fetch_assoc($stats);$totalAll=(int)$sr['total'];$totalActive=(int)$sr['active'];$totalResponded=(int)$sr['responded'];$totalDisabled=(int)$sr['disabled'];}}$participation=$totalAll?round($totalResponded/$totalAll*100,1):0;admin_page_start('Participants','participants');?>
<div class="hero"><div><h2>Participant accounts</h2><p>Generate unique login IDs and temporary passwords, then track who has submitted feedback.</p></div><a class="btn" href="generate.php<?= $campaignId?'?campaign_id='.$campaignId:'' ?>"><i class="fa-solid fa-users-gear"></i> Generate accounts</a></div><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><?php if($issued):?><div class="alert"><strong>Save these credentials now:</strong> <?=h($issued['name'])?> · Code <strong><?=h($issued['code'])?></strong> · Password <strong><?=h($issued['password'])?></strong>. The password will not be shown again.</div><?php endif;?><div class="card"><form method="get" class="form-grid"><div class="field full"><label>Campaign</label><select name="campaign_id" onchange="this.form.submit()"><option value="">Choose a campaign…</option><?php if($campaigns):while($c=pg_fetch_assoc($campaigns)):?><option value="<?=(int)$c['id']?>" <?=$campaignId===(int)$c['id']?'selected':''?>><?=h($c['title'])?> (<?=h($c['status'])?>)</option><?php endwhile;endif;?></select></div></form></div>
<?php if($campaign):?><div class="stats-grid"><div class="stat-card voters"><div class="stat-icon"><i class="fas fa-users"></i></div><div><div class="stat-number"><?=$totalAll?></div><div class="stat-label">Total Participants</div></div></div><div class="stat-card votes"><div class="stat-icon"><i class="fas fa-user-check"></i></div><div><div class="stat-number"><?=$totalActive?></div><div class="stat-label">Active (Can Respond)</div></div></div><div class="stat-card elections"><div class="stat-icon"><i class="fas fa-comment-dots"></i></div><div><div class="stat-number"><?=$totalResponded?></div><div class="stat-label">Already Responded</div></div></div><div class="stat-card turnout"><div class="stat-icon"><i class="fas fa-percentage"></i></div><div><div class="stat-number"><?=$participation?>%</div><div class="stat-label">Response Rate</div><div class="stat-sub"><?=$totalDisabled?> disabled</div></div></div></div><div class="quick-actions"><h3><i class="fas fa-bolt"></i> Account Actions</h3><div class="action-buttons"><a class="action-btn primary" href="generate.php?campaign_id=<?=$campaignId?>"><i class="fas fa-users-gear"></i> Generate Accounts</a><a class="action-btn info" href="template.php"><i class="fas fa-file-csv"></i> CSV Template</a><?php if(!empty($_SESSION['generated_participant_credentials'])):?><a class="action-btn success" href="credentials.php"><i class="fas fa-key"></i> Last Credentials</a><?php endif;?></div></div><div class="card"><h3>Add one participant</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="campaign_id" value="<?=$campaignId?>"><input type="hidden" name="action" value="create"><div class="field"><label>Full name</label><input name="full_name" required></div><div class="field"><label>Group / department</label><input name="group_name" placeholder="Optional"></div><div class="field"><label>Participant code</label><input name="participant_code" placeholder="Leave blank to generate"></div><div class="field"><label>Temporary password</label><input name="password" minlength="8" placeholder="Leave blank to generate"></div><div class="field full"><label>Confirm administrator password</label><input type="password" name="admin_password" required autocomplete="current-password"></div><div class="field full"><button class="btn">Create credentials</button></div></form></div>
<div class="card"><h3><?=h($campaign['title'])?> · Participants</h3><div class="table-wrap"><table><thead><tr><th>Code</th><th>Participant</th><th>Group</th><th>Status</th><th>Responded</th><th>Actions</th></tr></thead><tbody><?php if($participants):while($p=pg_fetch_assoc($participants)):?><tr><td><span class="badge"><?=h($p['participant_code'])?></span></td><td><strong><?=h($p['full_name'])?></strong></td><td><?=h($p['group_name']?:'—')?></td><td><span class="badge <?=h($p['status'])?>"><?=h(ucfirst($p['status']))?></span></td><td><?= $p['responded_at']?h(date('M j, Y g:i A',strtotime($p['responded_at']))):'—' ?></td><td><?php if($p['status']!=='responded'):?><div class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="campaign_id" value="<?=$campaignId?>"><input type="hidden" name="action" value="reset"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="btn small secondary">Reset password</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="campaign_id" value="<?=$campaignId?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="btn small <?= $p['status']==='disabled'?'':'danger' ?>"><?= $p['status']==='disabled'?'Enable':'Disable' ?></button></form></div><?php else:?><span class="help">Locked after response</span><?php endif;?></td></tr><?php endwhile;endif;if(!$participants||pg_num_rows($participants)===0):?><tr><td colspan="6" class="empty">No participants invited yet.</td></tr><?php endif;?></tbody></table></div></div><?php endif;admin_page_end();?>
